// Generated by scripts/build_web.py. Keeps what the app reads from the server on the device:
// mushaf pages, translations, search data and fonts are read once and then served from the cache.
// «hefz-keep» holds what the reader saved for use without internet (a whole surah with its recitation); it is never
// cleared by an update, and is used when the network is not there.
const CACHE = "hefz-7ba652c9b6ca", KEEP = "hefz-keep";
const DATA = /\/data\/(pages|trans)\/[^/]+\.json$|\/data\/(quran|roots|similar)\.json$|\/fonts\/[^/]+\.woff2$|\/icon-512\.png$|\/manifest\.webmanifest$/;
self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", e => e.waitUntil(caches.keys()
  .then(ks => Promise.all(ks.filter(k => k.startsWith("hefz-") && k !== CACHE && k !== KEEP).map(k => caches.delete(k))))
  .then(() => self.clients.claim())));
const keep = (req, res) => { if (res.ok) { const c = res.clone(); caches.open(CACHE).then(x => x.put(req, c)); } return res; };
const saved = r => caches.match(r, {ignoreVary: true});
self.addEventListener("fetch", e => {
  const r = e.request; if (r.method !== "GET") return;
  const u = new URL(r.url);
  // The page itself: always the newest from the server, the saved copy when offline
  if (r.mode === "navigate") { e.respondWith(fetch(r).then(res => keep(r, res)).catch(() => saved(r).then(x => x || saved(new URL("./", location.href).href)))); return; }
  // Recitation saved with a surah: from the device; everything else of it streams as before
  if (u.hostname === "everyayah.com") { e.respondWith(caches.open(KEEP).then(c => c.match(r.url)).then(hit => hit || fetch(r))); return; }
  const mine = u.origin === location.origin && DATA.test(u.pathname);
  const cdn = u.hostname === "cdn.jsdelivr.net" && u.pathname.includes("/quran-qcf4@");
  const gf = u.hostname === "fonts.googleapis.com" || u.hostname === "fonts.gstatic.com";
  if (!mine && !cdn && !gf) return;
  e.respondWith(caches.open(CACHE).then(c => c.match(r)).then(hit => hit || fetch(r).then(res => keep(r, res)).catch(() => saved(r).then(x => x || Promise.reject(new Error("offline"))))));
});
